mapper.select:


  p.del_flag='0' and p.status='PUBLISHED'
  and p.shop_user_id=#{authorId}
  and p.place_id=#{placeId}
  and p.merchant_id=#{merchantId}
  and p.status=#{status}
  and p.published_at >= #{publishedFrom}
  and p.published_at <= #{publishedTo}
  and p.place_city=#{city}
  and (p.title like concat('%',#{keyword},'%') or u.user_name like concat('%',#{keyword},'%') or u.nick_name like concat('%',#{keyword},'%') or p.place_name like concat('%',#{keyword},'%'))
  and p.perspective='LOCAL'
  and p.perspective='TOURIST'
  and p.perspective='HOMETOWNER'
  and p.featured_flag='1'
  and p.featured_flag='0'

order by p.published_at desc,p.post_id desc


where p.del_flag='0'
  and p.status='PUBLISHED'
  and p.featured_flag='1'
  and p.place_city=#{city}
order by p.featured_at desc,p.published_at desc,p.post_id desc
limit #{limit}
